//COPYJOB JOB (ACCT),'COPY DATA',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=INPUT.DATASET,DISP=SHR
//SYSUT2  DD DSN=OUTPUT.DATASET,DISP=(NEW,CATLG),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//LISTJOB JOB (ACCT),'LIST PDS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=SYS1.PARMLIB(IEASYS00),DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//DELJOB  JOB (ACCT),'DELETE DS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DELDD   DD DSN=MY.OLD.DATASET,DISP=(OLD,DELETE)

//ALLOCJOB JOB (ACCT),'ALLOC DS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//NEWDS   DD DSN=MY.NEW.DATASET,DISP=(NEW,CATLG),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA,
//           DCB=(RECFM=FB,LRECL=80,BLKSIZE=800)

//LISTCAT JOB (ACCT),'LISTCAT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  LISTCAT ENTRIES(MY.DATASET.*) ALL
/*

//SORTJOB JOB (ACCT),'SORT FILE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=SORT
//SORTIN  DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA
//SYSOUT  DD SYSOUT=*
//SYSIN   DD *
  SORT FIELDS=(1,10,CH,A)
/*

//DEFKSDS JOB (ACCT),'DEF VSAM',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  DEFINE CLUSTER (NAME(MY.VSAM.KSDS) -
         INDEXED -
         KEYS(10 0) -
         RECORDSIZE(100 100) -
         TRACKS(10 5)) -
         DATA (NAME(MY.VSAM.KSDS.DATA)) -
         INDEX (NAME(MY.VSAM.KSDS.INDEX))
/*

//ALLOC   JOB (ACCT),'ALLOCATE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=MY.NEW.FILE,DISP=(NEW,CATLG),
//           SPACE=(TRK,(1,1)),UNIT=SYSDA

//COPY    JOB (ACCT),'COPY',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=INPUT.FILE,DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//PRINT   JOB (ACCT),'PRINT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=MY.DATA,DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//TWOSTEP JOB (ACCT),'TWO STEPS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//STEP2   EXEC PGM=IEFBR14

//COMMENT JOB (ACCT),'COMMENTS',CLASS=A,MSGCLASS=X
//* THIS IS A COMMENT
//STEP1   EXEC PGM=IEFBR14
//* END OF JOB

//GDGJOB  JOB (ACCT),'CREATE GDG',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  DEFINE GDG (NAME(MY.GDG.BASE) LIMIT(5) SCRATCH)
/*

//DELVSAM JOB (ACCT),'DEL VSAM',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  DELETE MY.VSAM.FILE CLUSTER
/*

//REPRO   JOB (ACCT),'REPRO',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//INPUT   DD DSN=INPUT.FILE,DISP=SHR
//OUTPUT  DD DSN=OUTPUT.FILE,DISP=SHR
//SYSIN   DD *
  REPRO INFILE(INPUT) OUTFILE(OUTPUT)
/*

//COMPRESS JOB (ACCT),'COMPRESS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBCOPY
//SYSPRINT DD SYSOUT=*
//SYSUT1  DD DSN=MY.PDS,DISP=OLD
//SYSUT2  DD DSN=MY.PDS,DISP=OLD
//SYSIN   DD *
  COPY INDD=SYSUT1,OUTDD=SYSUT2
/*

//BACKUP  JOB (ACCT),'BACKUP',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=PROD.DATA,DISP=SHR
//SYSUT2  DD DSN=BACKUP.DATA,DISP=(NEW,CATLG),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//CONCAT  JOB (ACCT),'CONCAT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=FILE1,DISP=SHR
//        DD DSN=FILE2,DISP=SHR
//        DD DSN=FILE3,DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//SORTASC JOB (ACCT),'SORT ASC',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=SORT
//SORTIN  DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG),SPACE=(TRK,(10,5))
//SYSOUT  DD SYSOUT=*
//SYSIN   DD *
  SORT FIELDS=(1,10,CH,A)
/*

//SORTDSC JOB (ACCT),'SORT DESC',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=SORT
//SORTIN  DD DSN=INPUT.FILE,DISP=SHR
//SORTOUT DD DSN=OUTPUT.FILE,DISP=(NEW,CATLG),SPACE=(TRK,(10,5))
//SYSOUT  DD SYSOUT=*
//SYSIN   DD *
  SORT FIELDS=(1,10,CH,D)
/*

//MERGE   JOB (ACCT),'MERGE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=SORT
//SORTIN01 DD DSN=FILE1,DISP=SHR
//SORTIN02 DD DSN=FILE2,DISP=SHR
//SORTOUT DD DSN=MERGED,DISP=(NEW,CATLG),SPACE=(TRK,(10,5))
//SYSOUT  DD SYSOUT=*
//SYSIN   DD *
  MERGE FIELDS=(1,10,CH,A)
/*

//IFJOB   JOB (ACCT),'IF THEN',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//        IF STEP1.RC = 0 THEN
//STEP2   EXEC PGM=IEFBR14
//        ELSE
//STEP3   EXEC PGM=IEFBR14
//        ENDIF

//UPDTE   JOB (ACCT),'UPDATE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBUPDTE,PARM=NEW
//SYSPRINT DD SYSOUT=*
//SYSUT2  DD DSN=MY.PDS,DISP=OLD
//SYSIN   DD *
./ ADD NAME=MEMBER
DATA LINE 1
DATA LINE 2
/*

//TSOJOB  JOB (ACCT),'TSO',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IKJEFT01
//SYSPRINT DD SYSOUT=*
//SYSTSPRT DD SYSOUT=*
//SYSTSIN DD *
  LISTCAT
/*

//MODJOB  JOB (ACCT),'MOD',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=NEW.DATA,DISP=SHR
//SYSUT2  DD DSN=EXIST.DATA,DISP=MOD
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//DUMMYJOB JOB (ACCT),'DUMMY',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=MYPROG
//INPUT   DD DUMMY
//OUTPUT  DD SYSOUT=*

//DSNDISP JOB (ACCT),'DSN DISP',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=MY.DATASET,DISP=SHR

//SYSOUTA JOB (ACCT),'SYSOUT A',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=MY.DATA,DISP=SHR
//SYSUT2  DD SYSOUT=A
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//DCBJOB  JOB (ACCT),'DCB',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=NEW.FILE,DISP=(NEW,CATLG),
//           DCB=(RECFM=FB,LRECL=80,BLKSIZE=8000),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA

//SPACEJOB JOB (ACCT),'SPACE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=NEW.FILE,DISP=(NEW,CATLG),
//           SPACE=(CYL,(5,2)),UNIT=SYSDA

//UNITJOB JOB (ACCT),'UNIT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=NEW.FILE,DISP=(NEW,CATLG),
//           SPACE=(TRK,(1,1)),UNIT=SYSDA

//DSSUJOB JOB (ACCT),'ADRDSSU',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=ADRDSSU
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  DUMP DS(INCLUDE(MY.DATA.**)) -
       OUTDD(TAPE)
/*
//TAPE    DD DSN=BACKUP.TAPE,DISP=(NEW,CATLG),UNIT=TAPE

//LISTJOB JOB (ACCT),'IEHLIST',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEHLIST
//SYSPRINT DD SYSOUT=*
//DD1     DD VOL=SER=VOL001,UNIT=SYSDA,DISP=SHR
//SYSIN   DD *
  LISTVTOC VOL=SYSDA=VOL001
/*

//RESTART JOB (ACCT),'RESTART',CLASS=A,MSGCLASS=X,RESTART=STEP3
//STEP1   EXEC PGM=IEFBR14
//STEP2   EXEC PGM=IEFBR14
//STEP3   EXEC PGM=IEFBR14

//FTPJOB  JOB (ACCT),'FTP',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=FTP
//SYSPRINT DD SYSOUT=*
//OUTPUT  DD SYSOUT=*
//INPUT   DD *
  HOSTNAME
  USER FTPUSER
  GET REMOTE.FILE LOCAL.FILE
  QUIT
/*

//ALIAS   JOB (ACCT),'ALIAS',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  DEFINE ALIAS (NAME(MYALIAS) RELATE(MY.DATASET))
/*

//PRINT   JOB (ACCT),'IEBPTPCH',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBPTPCH
//SYSPRINT DD SYSOUT=*
//SYSUT1  DD DSN=MY.DATA,DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSIN   DD *
  PRINT MAXFLDS=1
  RECORD FIELD=(80)
/*

//LISTALL JOB (ACCT),'LISTCAT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  LISTCAT ENTRIES(MY.DATA.**) ALL
/*

//ALTER   JOB (ACCT),'ALTER',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  ALTER MY.VSAM.FILE SHAREOPTIONS(2 3)
/*

//VERIFY  JOB (ACCT),'VERIFY',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  VERIFY FILE(DD1)
/*
//DD1     DD DSN=MY.VSAM.FILE,DISP=SHR

//EXAMINE JOB (ACCT),'EXAMINE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  EXAMINE NAME(MY.VSAM.FILE) INDEXTEST DATATEST
/*

//PRINTVSM JOB (ACCT),'PRINT VSAM',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//DD1     DD DSN=MY.VSAM.FILE,DISP=SHR
//SYSIN   DD *
  PRINT INFILE(DD1) COUNT(100)
/*

//THREESTP JOB (ACCT),'THREE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//STEP2   EXEC PGM=IEFBR14
//STEP3   EXEC PGM=IEFBR14

//BLDIDX  JOB (ACCT),'BLDINDEX',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN   DD *
  BLDINDEX INDATASET(MY.VSAM.KSDS) -
           OUTDATASET(MY.VSAM.AIX)
/*

//EXPORT  JOB (ACCT),'EXPORT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//BACKUP  DD DSN=BACKUP.FILE,DISP=(NEW,CATLG),UNIT=TAPE
//SYSIN   DD *
  EXPORT MY.VSAM.FILE OUTFILE(BACKUP)
/*

//IMPORT  JOB (ACCT),'IMPORT',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//BACKUP  DD DSN=BACKUP.FILE,DISP=SHR
//SYSIN   DD *
  IMPORT INFILE(BACKUP) OUTDATASET(MY.VSAM.FILE)
/*

//COPYMEM JOB (ACCT),'COPY MEM',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBCOPY
//SYSPRINT DD SYSOUT=*
//INDD    DD DSN=SOURCE.PDS,DISP=SHR
//OUTDD   DD DSN=TARGET.PDS,DISP=SHR
//SYSIN   DD *
  COPY INDD=INDD,OUTDD=OUTDD
  SELECT MEMBER=MYMEMBER
/*

//GDGGEN  JOB (ACCT),'GDG GEN',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=INPUT.DATA,DISP=SHR
//SYSUT2  DD DSN=MY.GDG(+1),DISP=(NEW,CATLG),
//           SPACE=(TRK,(10,5)),UNIT=SYSDA
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//GDGREAD JOB (ACCT),'GDG READ',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=MY.GDG(0),DISP=SHR
//SYSUT2  DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//OUTJOB  JOB (ACCT),'OUTPUT',CLASS=A,MSGCLASS=X
//OUT1    OUTPUT DEST=LOCAL,COPIES=2
//STEP1   EXEC PGM=IEBGENER
//SYSUT1  DD DSN=MY.DATA,DISP=SHR
//SYSUT2  DD SYSOUT=*,OUTPUT=*.OUT1
//SYSPRINT DD SYSOUT=*
//SYSIN   DD DUMMY

//ICETOOL JOB (ACCT),'ICETOOL',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=ICETOOL
//TOOLMSG DD SYSOUT=*
//DFSMSG  DD SYSOUT=*
//IN      DD DSN=INPUT.FILE,DISP=SHR
//OUT     DD SYSOUT=*
//TOOLIN  DD *
  DISPLAY FROM(IN) LIST(OUT) -
          HEADER('REPORT') DATE
/*

//COMPARE JOB (ACCT),'COMPARE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBCOMPR
//SYSPRINT DD SYSOUT=*
//SYSUT1  DD DSN=FILE1,DISP=SHR
//SYSUT2  DD DSN=FILE2,DISP=SHR
//SYSIN   DD *
  COMPARE TYPORG=PS
/*

//SUPERCE JOB (ACCT),'SUPERCE',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=ISRSUPC
//NEWDD   DD DSN=NEW.FILE,DISP=SHR
//OLDDD   DD DSN=OLD.FILE,DISP=SHR
//OUTDD   DD SYSOUT=*
//SYSIN   DD *
  CMPCOLM 1:80
/*

//ICEMAN  JOB (ACCT),'ICEMAN',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=ICEMAN
//SYSPRINT DD SYSOUT=*
//SORTIN  DD DSN=INPUT,DISP=SHR
//SORTOUT DD DSN=OUTPUT,DISP=(NEW,CATLG),SPACE=(TRK,(10,5))
//SYSIN   DD *
  SORT FIELDS=(1,10,CH,A)
/*

//REFERJOB JOB (ACCT),'REFER',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEFBR14
//DD1     DD DSN=MY.FILE,DISP=(NEW,CATLG),
//           DCB=(RECFM=FB,LRECL=80,BLKSIZE=8000),
//           SPACE=(TRK,(10,5))
//DD2     DD DSN=ANOTHER.FILE,DISP=(NEW,CATLG),
//           DCB=*.DD1,SPACE=(TRK,(5,2))

//IEBDGJOB JOB (ACCT),'IEBDG',CLASS=A,MSGCLASS=X
//STEP1   EXEC PGM=IEBDG
//SYSPRINT DD SYSOUT=*
//SEQOUT  DD DSN=TEST.DATA,DISP=(NEW,CATLG),
//           DCB=(RECFM=FB,LRECL=80,BLKSIZE=800),
//           SPACE=(TRK,(1,1))
//SYSIN   DD *
  DSD OUTPUT=(SEQOUT)
  FD NAME=FIELD1,LENGTH=80,PICTURE=80,'TEST RECORD'
  CREATE QUANTITY=10,NAME=FIELD1
  END
/*
